import {HistoryTree} from './history-tree.js';
export class ProjectSession{
 constructor(adapter){this.a=adapter;this.entries=[];this.closed=[];this.active=null;this.busy=false;}
 stash(){if(!this.active)return;const e=this.entries.find(e=>e.id===this.active);if(e)Object.assign(e,this.a.capture());}
 async activate(id){if(this.busy||id===this.active)return;this.busy=true;try{this.stash();const e=this.entries.find(e=>e.id===id);if(!e)throw new Error('工程不存在');await this.a.restore(e);this.active=id;this.a.changed();}finally{this.busy=false;}}
 async open(snapshot,label,history,options={}){if(this.entries.length>=100)throw new Error('最多同时打开100个工程，请先关闭部分标签');if(this.busy)throw new Error('正在切换工程');this.stash();const e={id:crypto.randomUUID(),snapshot,history:history||new HistoryTree(snapshot,label||'新建工程').toJSON(),view:{},saved:options.saved??snapshot,savedNode:options.savedNode??null,manualSaved:options.manualSaved??false};this.entries.push(e);this.busy=true;try{await this.a.restore(e);this.active=e.id;this.a.changed();}catch(err){this.entries=this.entries.filter(x=>x!==e);throw err;}finally{this.busy=false;}}
 async close(id){if(this.busy)return;this.stash();const i=this.entries.findIndex(e=>e.id===id);if(i<0)return;const e=this.entries[i];if(e.saved!==e.snapshot&&this.a.beforeClose&&!await this.a.beforeClose(e))return;if(id===this.active){const next=this.entries[i+1]||this.entries[i-1];if(next)await this.activate(next.id);else{await this.open(this.a.blank(),'新建工程');}}this.entries=this.entries.filter(x=>x.id!==id);this.closed.push(e);this.a.changed();}
 async reopen(id){const e=this.closed.find(e=>e.id===id);if(!e)return;this.closed=this.closed.filter(x=>x!==e);this.entries.push(e);await this.activate(e.id);}
 bundle(){this.stash();return {version:1,active:this.active,entries:this.entries,closed:this.closed};}
 async restoreBundle(data){if(!data||data.version!==1||!Array.isArray(data.entries)||!data.entries.length||data.entries.length>100)return false;for(const e of [...data.entries,...data.closed||[]]){if(typeof e.id!=='string'||typeof e.snapshot!=='string')return false;HistoryTree.from(e.history);if(typeof e.saved!=='string'){e.saved=e.history.nodes[0].snapshot;e.manualSaved=false;}e.savedNode??=e.history.nodes.find(n=>n.snapshot===e.saved)?.id||null;}this.entries=data.entries;this.closed=data.closed||[];const e=this.entries.find(e=>e.id===data.active)||this.entries[0];await this.a.restore(e);this.active=e.id;this.a.changed();return true;}
}
